    (v_route, 'Ještěd', 'Vysílač v okrese Liberec. Rozhledna v Česku — výhled do kraje jako odměna za zastávku.', 50.73263, 14.98459, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jested%20002.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jested%20002.JPG"}'::text[], 4, '{"en": {"name": "Ještěd Tower", "description": "Tower in the Czech Republic. A lookout tower in Czechia — sweeping views as a reward for stopping."}, "de": {"name": "Fernsehturm Ještěd", "description": "Bauwerk auf den Jeschken, Tschechien. Ein Aussichtsturm in Tschechien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Hotel i nadajnik telewizyjny na górze Ještěd", "description": "Hotel i nadajnik telewizyjny w Czechach. Wieża widokowa w Czechach — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Ještěd", "description": "Uitkijktoren in Liberec, Tsjechië. Een uitkijktoren in Tsjechië — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Ještěd", "description": "Un mirador en Chequia: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de Ještěd", "description": "Tour en République tchèque. Une tour panoramique en Tchéquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Вежа Йештед", "description": "Оглядова вежа в Чехії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
