  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'most Slovenského národního povstání', 'Most přes Dunaj v Bratislavě. Rozhledna v Slovensku — výhled do kraje jako odměna za zastávku.', 48.13833, 17.10444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20New%20Bridge%20from%20castle%20hill.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20New%20Bridge%20from%20castle%20hill.JPG"}'::text[], 0, '{"en": {"name": "Bridge of the Slovak National Uprising", "description": "Bridge over Danube in Bratislava, Slovakia. A lookout tower in Slovakia — sweeping views as a reward for stopping."}, "de": {"name": "Brücke des Slowakischen Nationalaufstandes", "description": "Brücke über die Donau in Bratislava. Ein Aussichtsturm in der Slowakei — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Most SNP", "description": "Most nad Dunajem. Wieża widokowa w Słowacji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Nový Most", "description": "Brug voor wegverkeer over de Donau in Bratislava. Een uitkijktoren in Slowakije — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Most SNP", "description": "Un mirador en Eslovaquia: amplias vistas como recompensa por la parada."}, "fr": {"name": "pont du Soulèvement national slovaque", "description": "Pont de Bratislava. Une tour panoramique en Slovaquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Міст СНП", "description": "Міст у Братиславі. Оглядова вежа в Словаччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Katedrála svatého Martina v Bratislavě', 'Katedrála v Bratislavě. Památka v Slovensku — kus historie přímo u trasy.', 48.14194, 17.10472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava-Dom-sv-Martina.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava-Dom-sv-Martina.jpg"}'::text[], 1, '{"en": {"name": "St. Martin''s Cathedral, Bratislava", "description": "Cathedral. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Martinsdom", "description": "Kirchengebäude in Bratislava. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Marcina w Bratysławie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "St. Martin''s Cathedral", "description": "Kathedraal in Bratislava, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Martín", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Martin de Bratislava", "description": "Cathédrale de Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Братиславський собор", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
