    (v_route, 'Televizní věž na Kamzíku', 'Rozhledna v Slovensku — výhled do kraje jako odměna za zastávku.', 48.1825, 17.09444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Fernsehturm%20%28a%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bratislava%20-%20Fernsehturm%20%28a%29.JPG"}'::text[], 4, '{"en": {"name": "Kamzík TV Tower", "description": "Observation tower. A lookout tower in Slovakia — sweeping views as a reward for stopping."}, "de": {"name": "Fernsehturm Bratislava", "description": "Ein Aussichtsturm in der Slowakei — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża telewizyjna Kamzík", "description": "Wieża widokowa w Słowacji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Televizní věž na Kamzíku", "description": "Uitkijktoren in Slowakije. Een uitkijktoren in Slowakije — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de TV de Kamzík", "description": "Un mirador en Eslovaquia: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de télévision du Kamzík", "description": "Une tour panoramique en Slovaquie — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Televizní věž na Kamzíku", "description": "Оглядова вежа в Словаччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Katedrála svatého Šebastiána', 'Katedrála v Bratislavě. Památka v Slovensku — kus historie přímo u trasy.', 48.19575, 17.14302, 'http://commons.wikimedia.org/wiki/Special:FilePath/Katedr%C3%A1la%20sv%C3%A4t%C3%A9ho%20%C5%A0ebasti%C3%A1na%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Katedr%C3%A1la%20sv%C3%A4t%C3%A9ho%20%C5%A0ebasti%C3%A1na%2001.jpg"}'::text[], 5, '{"en": {"name": "St. Sebastian''s Cathedral, Bratislava", "description": "Church building in Rača, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kathedrale des heiligen Sebastian", "description": "Kirchengebäude in Bratislava. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Sebastiana w Bratysławie", "description": "Kościół katolicki. Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedrale des heiligen Sebastian", "description": "Kerkgebouw in Bratislava, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Sebastián", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Sébastien de Bratislava", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Šebastiána", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
