  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Dobšinská ledová jeskyně', 'Národní přírodní památka. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.86833, 20.30444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dobsinska%20ladova%20cave.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dobsinska%20ladova%20cave.jpg"}'::text[], 0, '{"en": {"name": "Dobšinská Ice Cave", "description": "Cave in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Dobšinská ľadová jaskyňa", "description": "Eishöhle in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Dobszyńska Jaskinia Lodowa", "description": "Jaskinia turystyczna (Powiat Rożniawa, Słowacja). Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Dobšinská-ijsgrot", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de hielo de Dobšinská", "description": "Cueva de hielo ubicada en Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte de glace de Dobšiná", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Добшинська крижана печера", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Národní park Slovenský ráj', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.90833, 20.4, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovensky%20raj-Stratenska%20pila.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovensky%20raj-Stratenska%20pila.jpg"}'::text[], 1, '{"en": {"name": "Slovak Paradise National Park", "description": "National park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Slowakisches Paradies", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Słowacki Raj", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Slowaaks Paradijs", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional del Paraíso Eslovaco", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national du Paradis slovaque", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Словацький Рай", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Konkatedrála Sedmibolestné Panny Marie', 'Katedrála v Popradě. Památka v Slovensku — kus historie přímo u trasy.', 49.05615, 20.29737, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Poprad.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slovakia%20Poprad.jpg"}'::text[], 2, '{"en": {"name": "Our Lady of Sorrows Church, Poprad", "description": "Cathedral. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Konkathedrale zum Gedächtnis der Sieben Schmerzen Mariens", "description": "Kathedrale in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Konkatedra Siedmiu Boleści Najświętszej Maryi Panny w Popradzie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Our Lady of Sorrows Church, Poprad", "description": "Kathedraal in Poprad, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Concatedral de Nuestra Señora de los Dolores", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "concathédrale Notre-Dame-aux-Sept-Douleurs de Poprad", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Konkatedrála Sedmibolestné Panny Marie", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel svatého Jakuba', 'Bazilika v Levoči. Památka v Slovensku — kus historie přímo u trasy.', 49.0263, 20.5891, 'http://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20St.%20James%20in%20Levo%C4%8Da.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20St.%20James%20in%20Levo%C4%8Da.jpg"}'::text[], 3, '{"en": {"name": "St. James, Levoča", "description": "Gothic Basilica minor, World Heritage Site, highest wooden altar, well-preserved interior. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "St. Jakob (Levoča)", "description": "Kirchengebäude in der Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Jakuba w Lewoczy", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kostel svatého Jakuba", "description": "Kerkgebouw in Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de Santiago (Levoča)", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Jacques", "description": "Église à Levoča en Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kostel svatého Jakuba", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
