    (v_route, 'Ochtinská aragonitová jeskyně', 'Národní přírodní památka. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.66472, 20.30917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ochtina%20Aragonite%20Cave%2014.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ochtina%20Aragonite%20Cave%2014.jpg"}'::text[], 5, '{"en": {"name": "Ochtinská Aragonite Cave", "description": "Cave in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Ochtinská aragonitová jaskyňa", "description": "Höhle in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Ochtyńska Jaskinia Aragonitowa", "description": "Jaskinia turystyczna (Powiat Rożniawa, Słowacja). Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Ochtinská aragonitová jaskyňa", "description": "Grot. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de aragonito Ochtinská", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte d''aragonite d''Ochtiná", "description": "Grotte en Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Охтинська арагонітова печера", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Muráňský hrad', 'Zřícenina hradu na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.75861, 20.05861, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88%20Castle%20gate%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88%20Castle%20gate%2001.JPG"}'::text[], 6, '{"en": {"name": "Muráň Castle", "description": "Castle. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Muráň", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Murań", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Muráňský hrad", "description": "Kasteel in Muráň, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Muráňský hrad", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "Muráňský hrad", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Muráňský hrad", "description": "Замок (споруда). Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Národní park Muráňská planina', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.78333, 20.03333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88sk%C3%A1%20planina%20%282%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mur%C3%A1%C5%88sk%C3%A1%20planina%20%282%29.JPG"}'::text[], 7, '{"en": {"name": "Muránska planina National Park", "description": "Slovak national park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Muraner Hochebene", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Płaskowyż Murański", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Muránska Planina", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Muránska Planina", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Muránska planina", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк Муранська полонина", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb);
