    (v_route, 'Býčí skála', 'Jeskyně v Moravském krasu. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.30746, 16.69478, 'http://commons.wikimedia.org/wiki/Special:FilePath/Byci%20skala%204.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Byci%20skala%204.JPG"}'::text[], 6, '{"en": {"name": "Býčí skála Cave", "description": "Cave. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Stierfelsen", "description": "Höhle in Tschechien. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Býčí skála", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Býčí skála", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Býčí skála", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "grotte de Býčí skála", "description": "Grotte en Tchéquie. Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Býčí skála", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Moravský kras', 'Krasová oblast v Česku, geomorfologický podcelek Drahanské vrchoviny. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.27806, 16.73417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jakubovo%20jezero%20%28Moravsky%20kras%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jakubovo%20jezero%20%28Moravsky%20kras%29.JPG"}'::text[], 7, '{"en": {"name": "Moravian Karst", "description": "Karst landscape and protected landscape area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Mährischer Karst", "description": "Gebirgszug. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kras Morawski", "description": "Jaskinia turystyczna (Powiat Blansko, Czechy). Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Moravische Karst", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Karst de Moravia", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Karst Morave", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Моравський карст", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
