    (v_route, 'Národní park Slovenský kras', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.579, 20.544, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zadielska%20tiesnava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zadielska%20tiesnava.jpg"}'::text[], 0, '{"en": {"name": "Slovak Karst National Park", "description": "National park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Slowakischer Karst", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Kras Słowacki", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Slowaakse Karst", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Slovenský Kras", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national du karst de Slovaquie", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк «Словацький карст»", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
