    (v_route, 'Krásna Hôrka', 'Hrad. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 48.65824, 20.60033, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kr%C3%A1sna%20H%C3%B4rka%201.JPG"}'::text[], 6, '{"en": {"name": "Krásna Hôrka Castle", "description": "Castle. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Krásna Hôrka", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Krásna Hôrka", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Krásna Hôrka", "description": "Kasteel in Krásnohorské Podhradie, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Krásna Hôrka", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Krásna Hôrka", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Красна Гурка", "description": "Замок (споруда). Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
