    (v_route, 'Černé jezero', 'Jezero na Šumavě v České republice. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.17917, 13.1825, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A9%20Jezero%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A9%20Jezero%20-%20panoramio.jpg"}'::text[], 0, '{"en": {"name": "Černé jezero", "description": "Lake in Železná Ruda, Plzeň Region, Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Černé jezero", "description": "Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Černé jezero", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Černé jezero", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Černé", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Černé jezero", "description": "Lac de République tchèque. Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Чорне озеро", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
