    (v_route, 'Stužica', 'Národní přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.08333, 22.53333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stu%C5%BEica%20primeval%20forest%2C%20Slovakia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stu%C5%BEica%20primeval%20forest%2C%20Slovakia.jpg"}'::text[], 0, '{"en": {"name": "Stužica", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationales Naturreservat Stužica", "description": "Naturreservat. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Stužica", "description": "Pierwotny las bukowy z listy UNESCO położony w słowackich Bieszczadach. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Stužica", "description": "Natuurgebied in Okres Snina, Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Stužica", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Stužica", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Стужиця", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Národní park Poloniny', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.07139, 22.53361, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Eurkovec%20%28poh%C4%BEad%20z%20%C4%8Eurkovca%29%20001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Eurkovec%20%28poh%C4%BEad%20z%20%C4%8Eurkovca%29%20001.jpg"}'::text[], 1, '{"en": {"name": "Poloniny National Park", "description": "National park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Poloniny", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Połoniny", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "nationaal park Poloniny", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Poloniny", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national des Poloniny", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Національний парк Полонини", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Biosférická rezervace Východní Karpaty', 'Přeshraniční chráněná oblast. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.0, 22.5, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tarnica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tarnica.jpg"}'::text[], 2, '{"en": {"name": "East Carpathian Transboundary Biosphere Reserve", "description": "Transboundary protected area of global importance under UNESCO''s Programme on Man and the Biosphere. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Grenzüberschreitendes Biosphärenreservat Ostkarpaten", "description": "UNESCO-Biosphärenreservat in Polen, der Ukraine und der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Międzynarodowy Rezerwat Biosfery \"Karpaty Wschodnie\"", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Oost-Karpatisch Biosfeerreservaat", "description": "Natuurgebied in Polen. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Reserva de la biosfera Carpática oriental", "description": "Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "réserve de biosphère des Carpates orientales", "description": "Réserve de biosphère en Pologne, en Slovaquie et en Ukraine. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Міжнародний біосферний резерват Східні Карпати", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Rožok', 'Národní přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 48.9833, 22.4647, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sk%20Rozok%20Dicke%20Buche%20liegend%20%2B.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sk%20Rozok%20Dicke%20Buche%20liegend%20%2B.jpg"}'::text[], 3, '{"en": {"name": "Rožok", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationales Naturreservat Rožok", "description": "Naturreservat in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rožok", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Oerbos Rožok", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Rozok", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Rožok", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Rožok", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Havešová', 'Národní přírodní rezervace. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.00969, 22.33603, 'http://commons.wikimedia.org/wiki/Special:FilePath/Primeval%20forest%20Have%C5%A1ov%C3%A1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Primeval%20forest%20Have%C5%A1ov%C3%A1.jpg"}'::text[], 4, '{"en": {"name": "Havešová", "description": "National nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationales Naturreservat Havešová", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Havešová", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Oerbos Havešová", "description": "Natuurgebied in Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Havesova", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Havešová", "description": "Aire protégée de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Гавешова", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Vodní nádrž Starina', 'Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.05639, 22.25361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Starina-trinkakvujo%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Starina-trinkakvujo%201.jpg"}'::text[], 5, '{"en": {"name": "Starina reservoir", "description": "Lake in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Starina-Stausee", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Starina", "description": "Zbiornik retencyjny (Stakčín, Słowacja). Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Starina reservoir", "description": "Stuwmeer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Starina", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Starina", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Старина (водосховище)", "description": "Водосховище на р. Ціроха, округ Сніна, Пряшівський край, Словаччина. Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Ruské sedlo', 'Přírodní zajímavost na Slovensku — místo na protažení nohou uprostřed přírody.', 49.14438, 22.33023, 'http://commons.wikimedia.org/wiki/Special:FilePath/Nad%20Roztokami%20pass%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Nad%20Roztokami%20pass%201.jpg"}'::text[], 6, '{"en": {"name": "Przełęcz nad Roztokami Górnymi/Ruské sedlo", "description": "A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Ruské sedlo", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Przełęcz nad Roztokami Górnymi", "description": "Atrakcja przyrodnicza na Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Ruské sedlo", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Ruské sedlo", "description": "Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Ruské sedlo", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Руске седло", "description": "Гірський перевал в масиві Буковски врхи, східна Словаччина. Природна пам''ятка у Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Udava', 'Přírodní rezervace na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.17778, 22.2225, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poloniny-PR-Udava2015g.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poloniny-PR-Udava2015g.jpg"}'::text[], 7, '{"en": {"name": "Udava", "description": "Nature reserve in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Naturreservat Udava", "description": "Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Udava", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Natuurreservaat Udava", "description": "Natuurgebied in Okres Snina, Slowakije. Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Udava", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Udava", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Udava", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb);
