    (v_route, 'Bouzov', 'Hrad na středozápadní Moravě. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.70444, 16.88972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bouzov%20hrad%20%28Burg%20Busau%29%20-%20by%20Pudelek%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bouzov%20hrad%20%28Burg%20Busau%29%20-%20by%20Pudelek%20%28cropped%29.jpg"}'::text[], 0, '{"en": {"name": "Bouzov Castle", "description": "Castle in the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Bouzov", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Bouzovie", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Bouzov", "description": "Kasteel in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Bouzov", "description": "Castillo de la República Checa. Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bouzov", "description": "Château en Tchéquie. Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Bouzov", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Mladečské jeskyně', 'Jeskyně v Chráněné krajinné oblasti Litovelské Pomoraví. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.7064, 17.0167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mlade%C4%8Dsk%C3%A1%20jeskyn%C4%9B%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mlade%C4%8Dsk%C3%A1%20jeskyn%C4%9B%201.JPG"}'::text[], 1, '{"en": {"name": "Mladeč caves", "description": "Cave and archaeological site in the Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Mladečské jeskyně", "description": "Höhle in Tschechien. Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Jaskinia Mladecka", "description": "Jaskinia turystyczna (Mladeč, Czechy). Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Mladečské jeskyně", "description": "Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Mladečské jeskyně", "description": "Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Mladečské jeskyně", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Mladečské jeskyně", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Hrad Šternberk', 'Hrad a národní kulturní památka, Šternberk, okres Olomouc. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.73306, 17.30167, 'http://commons.wikimedia.org/wiki/Special:FilePath/CZ%20Sternberg%20-%20Castle%203.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/CZ%20Sternberg%20-%20Castle%203.jpg"}'::text[], 2, '{"en": {"name": "Šternberk Castle", "description": "National monument, Šternberk, Olomouc District, Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Šternberk", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Šternberk", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Šternberk", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Hrad Šternberk", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Hrad Šternberk", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Hrad Šternberk", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Sovinec', 'Hrad v okrese Bruntál. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.83748, 17.24574, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sovinec%201848%20F%20A%20Heber.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sovinec%201848%20F%20A%20Heber.jpg"}'::text[], 3, '{"en": {"name": "Sovinec", "description": "Castle in the Bruntál District, Czechia. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Sovinec", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Sovinec", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Sovinec", "description": "Kasteel in Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Sovinec", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Sovinec", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Sovinec", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatého Václava v Olomouci', 'Kostel v Olomouci. Památka v Česku — kus historie přímo u trasy.', 49.59778, 17.2625, 'http://commons.wikimedia.org/wiki/Special:FilePath/Olomouc%20Katedrala%20Sv.%20Vaclava.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Olomouc%20Katedrala%20Sv.%20Vaclava.jpg"}'::text[], 4, '{"en": {"name": "Saint Wenceslas Cathedral", "description": "Church in Olomouc District of Olomouc region. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Wenzelsdom", "description": "Kathedrale in Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Wacława w Ołomuńcu", "description": "Świątynia katolicka. Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Wenceslas Cathedral", "description": "Kerkgebouw in Olomouc, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Venceslao", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Venceslas d''Olomouc", "description": "Église tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Святого Вацлава", "description": "Церква в Оломоуці, Чехія. Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
