    (v_route, 'Národní park Velká Fatra', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.01667, 19.11667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rakytov%2C%20Ve%C4%BEk%C3%A1%20Fatra%20%28SVK%29%20-%20southern%20side.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rakytov%2C%20Ve%C4%BEk%C3%A1%20Fatra%20%28SVK%29%20-%20southern%20side.jpg"}'::text[], 0, '{"en": {"name": "Veľká Fatra National Park", "description": "National park. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Große Fatra", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Wielka Fatra", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Veľká Fatra", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Veľká Fatra", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national Grande Fatra", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Národní park Velká Fatra", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
