    (v_route, 'Sĺňava', 'Vodní nádrž a chráněný areál na Slovensku. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.55639, 17.82583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slnava-plachetnica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slnava-plachetnica.jpg"}'::text[], 5, '{"en": {"name": "Sĺňava Reservoir", "description": "A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Sĺňava", "description": "Stausee in der Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Sĺňava", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Sĺňava", "description": "Stuwmeer in Okres Piešťany, Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Sĺňava", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Sĺňava", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Слнява (водосховище)", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
