    (v_route, 'Synagoga v Trenčíně', 'Národní kulturní památka v obci Trenčín, okrese Trenčín. Památka v Slovensku — kus historie přímo u trasy.', 48.89445, 18.03959, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%2C%20Trencin%20%282007%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%2C%20Trencin%20%282007%29.jpg"}'::text[], 7, '{"en": {"name": "Trenčín Synagogue", "description": "Former synagogue in Trenčín, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Gebäude in Trenčín, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Trenczynie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "synagoge van Trenčín", "description": "Bouwwerk in Trenčín. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Trenčíně", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Trenčín", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Trenčíně", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb);
