    (v_route, 'Veľké Hincovo pleso', 'Jezero ve Vysokých Tatrách. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.17917, 20.05972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Velke%20Hincovo%20pleso.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Velke%20Hincovo%20pleso.jpg"}'::text[], 0, '{"en": {"name": "Large Hincovo Lake", "description": "Lake. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Veľké Hincovo pleso", "description": "Gebirgssee der Hohen Tatra, Slowakei. Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Wielki Staw Hińczowy", "description": "Jezioro. Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Veľké Hincovo pleso", "description": "Meer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Veľké Hincovo pleso", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Veľké Hincovo pleso", "description": "Plus grand lac d’origine glaciaire de Slovaquie. Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Вельке Гінцово плесо", "description": "Озеро. Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Vodopád Skok', 'Vodopád ve Vysokých Tatrách. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.15269, 20.04567, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodopad%20Skok.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodopad%20Skok.jpg"}'::text[], 1, '{"en": {"name": "Vodopád Skok", "description": "Waterfall in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Skok (Wasserfall)", "description": "Wasserfall in der Hohen Tatra, Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Wodospad Skok", "description": "Wodospad w słowackich Tatrach Wysokich. Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Vodopád Skok", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "salto Skok", "description": "Salto de agua en Alto Tatra, Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Vodopád Skok", "description": "Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Скок", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
