    (v_route, 'Baňur', 'Jezero na Slovensku. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.21111, 20.66806, null, '{}'::text[], 1, '{"en": {"name": "Baňur", "description": "Body of water. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Baňur", "description": "Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Baňur", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Baňur", "description": "Meer in Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Baňur", "description": "Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Baňur", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Baňur", "description": "Водний об''єкт. Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
