    (v_route, 'Klášter Podolínec', 'Klášter a národní kulturní památka ve městě Podolínec, okrese Stará Ľubovňa, Slovensko. Památka v Slovensku — kus historie přímo u trasy.', 49.259, 20.5363, 'http://commons.wikimedia.org/wiki/Special:FilePath/Podol%C3%ADnec%20-%20Kl%C3%A1%C5%A1tor%20Piaristov.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Podol%C3%ADnec%20-%20Kl%C3%A1%C5%A1tor%20Piaristov.jpg"}'::text[], 3, '{"en": {"name": "Piarist monastery (Podolínec)", "description": "Monastery and national cultural monument in the town of Podolínec, Stará Ľubovňa district, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Klášter Podolínec", "description": "Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor pijarów w Podolińcu", "description": "Klasztor w Podolińcu w Słowacji. Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Klášter Podolínec", "description": "Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Klášter Podolínec", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Klášter Podolínec", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Podolínec", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Jezerské jazero', 'Přírodní rezervace. Vodní plocha v Slovensku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.28278, 20.34667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Jezersk%C3%A9%20jazero%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Jezersk%C3%A9%20jazero%201.jpg"}'::text[], 4, '{"en": {"name": "Jezerské jazero", "description": "Lake in Slovakia. A body of water in Slovakia — a pleasant ride destination with waterside views."}, "de": {"name": "Jezerské jazero", "description": "Ein Gewässer in der Slowakei — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezierskie Jezioro", "description": "Akwen w Słowacji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Jezerské jazero", "description": "Natuurgebied in Okres Kežmarok, Slowakije. Een waterpartij in Slowakije — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Jezerske jazero", "description": "Área protegida de Eslovaquia. Una masa de agua en Eslovaquia: un destino agradable con vistas al agua."}, "fr": {"name": "Jezerské jazero", "description": "Un plan d''eau en Slovaquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Jezerské jazero", "description": "Водойма в Словаччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Červený kláštor', 'Bývalý klášter na Slovensku. Památka v Slovensku — kus historie přímo u trasy.', 49.39861, 20.41722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Czerwony%20Klasztor%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Czerwony%20Klasztor%2002.jpg"}'::text[], 5, '{"en": {"name": "Červený Kláštor", "description": "Former Carthusian monastery; national cultural monument in the village of Červený Kláštor, Kežmarok district, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Červený Kláštor (Kloster)", "description": "Ehemaliges Kartäuserkloster; nationales Kulturdenkmal im Dorf Červený Kláštor, Bezirk Kežmarok, Slowakei. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Czerwony Klasztor (klasztor)", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Červený Kláštor", "description": "Klooster in Červený Kláštor, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio Rojo", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "chartreuse de Lechnica", "description": "Ancienne chartreuse en Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Červený kláštor", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Pieninský národní park', 'Národní park na Slovensku. Přírodní zajímavost v Slovensku — místo na protažení nohou uprostřed přírody.', 49.4, 20.45694, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dunajec%20and%20Lesnica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dunajec%20and%20Lesnica.jpg"}'::text[], 6, '{"en": {"name": "Pieniny National Park", "description": "National park in Slovakia. A natural sight in Slovakia — a spot to stretch your legs amid nature."}, "de": {"name": "Pieninen-Nationalpark", "description": "Nationalpark in der Slowakei. Eine Natursehenswürdigkeit in der Slowakei — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Pieniński Park Narodowy", "description": "Atrakcja przyrodnicza w Słowacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nationaal Park Pieniny", "description": "Een natuurbezienswaardigheid in Slowakije — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Pieniny", "description": "Área protegida de Eslovaquia. Un paraje natural en Eslovaquia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national des Pieniny", "description": "Parc national de Slovaquie. Un site naturel en Slovaquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "П’єніни", "description": "Природна пам''ятка в Словаччині — місце розім''яти ноги серед природи."}}'::jsonb),
