    (v_route, 'Synagoga v Českém Krumlově', 'Synagoga v okrese Český Krumlov. Památka v Česku — kus historie přímo u trasy.', 48.8076, 14.3174, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20%C4%8CK%2001b.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagoga%20%C4%8CK%2001b.jpg"}'::text[], 2, '{"en": {"name": "Synagogue in Český Krumlov", "description": "Synagogue in Český Krumlov District, Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Synagoge in Český Krumlov,  Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga v Českém Krumlově", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Českém Krumlově", "description": "Synagoge in Český Krumlov, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Českém Krumlově", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Český Krumlov", "description": "Bâtiment historique. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Českém Krumlově", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
