    (v_route, 'vodní nádrž Římov', 'Údolní nádrž na Malši v okrese Český Krumlov. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 48.8472, 14.4858, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20v%20%C5%98%C3%ADmov%C4%9B%20vypou%C5%A1t%C4%9Bj%C3%ADc%C3%AD%20vodu.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20v%20%C5%98%C3%ADmov%C4%9B%20vypou%C5%A1t%C4%9Bj%C3%ADc%C3%AD%20vodu.jpeg"}'::text[], 5, '{"en": {"name": "Římov Reservoir", "description": "A lake on the Malše, South Bohemian Region, Czechia. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Římov", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zbiornik wodny Římov", "description": "Sztuczne jezioro w Czechach. Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Římov", "description": "Stuwmeer in Římov, Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Římov", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Římov", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Římov", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
