    (v_route, 'synagoga ve Strážnici', 'Náboženská budova ve Strážnici, okres Hodonín, pouzívaná jako muzeum. Památka v Česku — kus historie přímo u trasy.', 48.90373, 17.31672, 'http://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice%2C%20synagogue%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice%2C%20synagogue%2001.jpg"}'::text[], 5, '{"en": {"name": "synagogue in Strážnice", "description": "Religious building in Strážnice, Hodonín District, Czechia, used as a museum. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Ehemalige Synagoge in Strážnice, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Strážnicach", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "synagoga ve Strážnici", "description": "Gebouw in Okres Hodonín, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "sinagoga en Strážnice", "description": "Edificio religioso en Strážnice, distrito de Hodonín, República Checa. Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagoga ve Strážnici", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "synagoga ve Strážnici", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Synagoga v Uherském Hradišti', 'Bývalá synagoga postavena v roce 1875 v novorománském slohu, v létě roku 1941 zničena a vypálena. Po roce 1945 přestavěna na kulturní dům, roku 1966 po velkém požáru budovy následovala další rekonstrukce. Dnes slouží budova jako městská knihovna Uher. Památka v Česku — kus historie přímo u trasy.', 49.0703, 17.4619, 'http://commons.wikimedia.org/wiki/Special:FilePath/Uherske%20Hradiste%20synagoga.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Uherske%20Hradiste%20synagoga.jpg"}'::text[], 6, '{"en": {"name": "Bedřich Beneš Buchlovan Library", "description": "A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge (Uherské Hradiště)", "description": "Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Uherskim Hradišciu", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Uherském Hradišti", "description": "Synagoge in Uherské Hradiště, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Uherském Hradišti", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Synagoga v Uherském Hradišti", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Uherském Hradišti", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
