    (v_route, 'Katedrála svatého Františka Xaverského', 'Katedrála v Banské Bystrici. Památka v Slovensku — kus historie přímo u trasy.', 48.73556, 19.14639, 'http://commons.wikimedia.org/wiki/Special:FilePath/P1020599.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/P1020599.JPG"}'::text[], 0, '{"en": {"name": "St. Francis Xavier Cathedral", "description": "Cathedral in Banská Bystrica, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kathedrale des heiligen Franz Xaver", "description": "Kathedrale der römisch-katholischen Diözese Banské Bystrice. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Franciszka Ksawerego w Bańskiej Bystrzycy", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "St. Francis Xavier Cathedral", "description": "Kathedraal in Banská Bystrica, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Francisco Javier", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-François-Xavier de Banská Bystrica", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Františka Xaverského", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
