    (v_route, 'Fortifikační systém města Komárno', 'Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 47.75333, 18.1375, 'http://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20bastion6.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20bastion6.jpg"}'::text[], 1, '{"en": {"name": "Fortifications of Komárno", "description": "Collection of forts defending Komárno. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Fortifikační systém města Komárno", "description": "Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Fortifikační systém města Komárno", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Fortifikační systém města Komárno", "description": "Museum in Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Fortifikační systém města Komárno", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "système de fortifications de Komárom", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Fortifikační systém města Komárno", "description": "Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
